<script setup>
import ContextPageHeading from '@/shared/presentation/components/ContextPageHeading.vue'
import { computed, reactive, ref } from 'vue'
import { useAuthStore } from '@/boundedcontext/identityaccess/application/stores/auth.store'
import { useSafeLabDemoStore } from '@/shared/application/stores/demo.store'
const auth = useAuthStore(); const demo = useSafeLabDemoStore(); auth.restoreSession()
const search = ref(''); const typeFilter = ref('all'); const statusFilter = ref('all'); const modalOpen = ref(false)
const form = reactive({})
const user = computed(() => auth.currentUser)
const facilities = computed(() => demo.scopedFacilities(user.value))
const sensors = computed(() => demo.scopedItems('sensors', user.value).filter((sensor) => {
  const text = `${sensor.name} ${sensor.code} ${sensor.type} ${sensor.responsible}`.toLowerCase()
  return text.includes(search.value.toLowerCase()) && (typeFilter.value === 'all' || sensor.type === typeFilter.value) && (statusFilter.value === 'all' || sensor.status === statusFilter.value)
}))
const summary = computed(() => ({ total: sensors.value.length, normal: sensors.value.filter((s) => s.status === 'normal').length, out: sensors.value.filter((s) => s.status === 'out-of-range').length, invalid: sensors.value.filter((s) => s.status === 'invalid' || s.connection !== 'online').length }))
function valueLabel(sensor){ return `${sensor.value}${sensor.unit || ''}` }
function resetForm() { Object.assign(form, { name: '', code: `SEN-${Date.now().toString().slice(-4)}`, type: 'temperature', unit: '°C', value: 4, min: 2, max: 8, facilityId: facilities.value[0]?.id || 'fac-central', responsible: user.value?.fullName || 'Operator' }) }
function openNew(){ resetForm(); modalOpen.value = true }
function save(){ demo.addSensor({ ...form, status: 'normal', connection: 'online' }); modalOpen.value = false }
</script>
<template>
  <section class="page">
    <div class="page-hero compact"><ContextPageHeading :description="$t('legacy.label_6878bee559')" /></div>
    <div class="records-quick-actions"><RouterLink class="btn records-view-button" to="/sensormonitoring/records/sensors"><i class="pi pi-list"></i> {{ $t('records.viewAll') }}</RouterLink></div>
<div class="page-toolbar"><button class="btn primary" @click="openNew"><i class="pi pi-plus"></i> {{ $t('legacy.label_352839b546') }}</button></div>
    <div class="kpi-grid"><article class="kpi-card"><span class="kpi-icon"><i class="pi pi-wifi"></i></span><div class="kpi-copy"><span>{{ $t('legacy.label_160f227c50') }}</span><strong>{{ summary.total }}</strong><small>{{ $t('legacy.label_15e87116e5') }}</small></div></article><article class="kpi-card success"><span class="kpi-icon"><i class="pi pi-check-circle"></i></span><div class="kpi-copy"><span>{{ $t('legacy.label_47feb6a782') }}</span><strong>{{ summary.normal }}</strong><small>{{ $t('legacy.label_e9dbbeb6c4') }}</small></div></article><article class="kpi-card danger"><span class="kpi-icon"><i class="pi pi-exclamation-triangle"></i></span><div class="kpi-copy"><span>{{ $t('legacy.label_a85ccda3fb') }}</span><strong>{{ summary.out }}</strong><small>{{ $t('legacy.label_6e641e5ec9') }}</small></div></article><article class="kpi-card warning"><span class="kpi-icon"><i class="pi pi-times-circle"></i></span><div class="kpi-copy"><span>{{ $t('legacy.label_54e07aad9d') }}</span><strong>{{ summary.invalid }}</strong><small>{{ $t('legacy.label_f61a646ef0') }}</small></div></article></div>
    <div class="filter-bar"><div class="field"><label>{{ $t('legacy.label_bce0641417') }}</label><input v-model="search" class="input" placeholder="Sensor, code or responsible"></div><div class="field"><label>{{ $t('legacy.label_3deb745651') }}</label><select v-model="typeFilter" class="select"><option value="all">{{ $t('legacy.label_30c8a0fc9c') }}</option><option value="temperature">{{ $t('legacy.label_0a9062a9cb') }}</option><option value="humidity">{{ $t('legacy.label_65adb9c296') }}</option><option value="door">{{ $t('legacy.label_478d47b06d') }}</option><option value="vibration">{{ $t('legacy.label_39b345e770') }}</option></select></div><div class="field"><label>{{ $t('legacy.label_bae7d5be70') }}</label><select v-model="statusFilter" class="select"><option value="all">{{ $t('legacy.label_6405179d24') }}</option><option value="normal">{{ $t('legacy.label_45e118d056') }}</option><option value="out-of-range">{{ $t('legacy.label_a85ccda3fb') }}</option><option value="invalid">{{ $t('legacy.label_54e07aad9d') }}</option></select></div><div class="actions"><button class="btn" type="button" @click="search=''; typeFilter='all'; statusFilter='all'">{{ $t('legacy.label_412226715c') }}</button></div></div>
    <div class="sensor-grid"><article v-for="sensor in sensors" :key="sensor.id" :class="['sensor-card', sensor.status !== 'normal' ? 'is-problem' : '']"><div class="card-header"><div><h3>{{ sensor.name }}</h3><p>{{ sensor.code }}</p></div><span :class="['status-pill', sensor.status]">{{ sensor.status }}</span></div><div class="sensor-value"><span class="text-muted">Current {{ sensor.type }}</span><strong>{{ valueLabel(sensor) }}</strong></div><div class="pair-grid"><div class="pair-box"><span>{{ $t('legacy.label_61ad50a9b9') }}</span><strong>{{ sensor.min }} - {{ sensor.max }}{{ sensor.unit }}</strong></div><div class="pair-box"><span>{{ $t('legacy.label_6512ee1541') }}</span><strong>{{ sensor.connection }}</strong></div><div class="pair-box"><span>{{ $t('legacy.label_96cd625f32') }}</span><strong>{{ sensor.responsible }}</strong></div><div class="pair-box"><span>{{ $t('legacy.label_30471bd8d6') }}</span><strong>{{ new Date(sensor.lastReading).toLocaleTimeString() }}</strong></div></div><div class="actions"><button class="btn small" @click="demo.updateSensor(sensor.id,{ value: sensor.type === 'temperature' ? Number(sensor.value)+1 : sensor.value })">{{ $t('legacy.label_5d307bd18a') }}</button><button class="btn small" @click="demo.updateSensor(sensor.id,{ value: sensor.type === 'temperature' ? 4 : sensor.type === 'humidity' ? 45 : sensor.value, status:'normal' })">{{ $t('legacy.label_61feacb17d') }}</button><button class="btn small danger" @click="demo.deleteSensor(sensor.id)">{{ $t('legacy.label_e963907dac') }}</button></div></article></div>
    <div v-if="modalOpen" class="modal-backdrop" @click.self="modalOpen=false"><article class="modal-card medium"><header class="modal-header"><div><p class="eyebrow">{{ $t('legacy.label_7fd2f6d272') }}</p><h2>{{ $t('legacy.label_7b3923434a') }}</h2></div><button class="icon-action" @click="modalOpen=false"><i class="pi pi-times"></i></button></header><form class="modal-form" @submit.prevent="save"><div class="field"><label>{{ $t('legacy.label_709a23220f') }}</label><input v-model="form.name" required class="input"></div><div class="field"><label>{{ $t('legacy.label_adac69379a') }}</label><input v-model="form.code" required class="input"></div><div class="field"><label>{{ $t('legacy.label_3deb745651') }}</label><select v-model="form.type" class="select"><option value="temperature">{{ $t('legacy.label_0a9062a9cb') }}</option><option value="humidity">{{ $t('legacy.label_65adb9c296') }}</option><option value="door">{{ $t('legacy.label_478d47b06d') }}</option><option value="vibration">{{ $t('legacy.label_39b345e770') }}</option></select></div><div class="field"><label>{{ $t('legacy.label_cd4d0c5e14') }}</label><select v-model="form.facilityId" class="select"><option v-for="facility in facilities" :key="facility.id" :value="facility.id">{{ facility.name }}</option></select></div><div class="field"><label>{{ $t('legacy.label_ed2757f1ed') }}</label><input v-model="form.value" class="input"></div><div class="field"><label>{{ $t('legacy.label_f6b935ab33') }}</label><input v-model="form.unit" class="input"></div><div class="field"><label>{{ $t('legacy.label_7eb0cee888') }}</label><input v-model="form.min" class="input"></div><div class="field"><label>{{ $t('legacy.label_a95e85aed5') }}</label><input v-model="form.max" class="input"></div><footer class="modal-footer full"><button class="btn" type="button" @click="modalOpen=false">{{ $t('legacy.label_77dfd2135f') }}</button><button class="btn success" type="submit">{{ $t('legacy.label_efc007a393') }}</button></footer></form></article></div>
  </section>
</template>
